/**
 * assistant-guards.js — output validation for the data assistant.
 *
 * Three stages, all deterministic:
 *   planGuards(question, data)   → which checks apply to THIS question
 *   checkAnswer(answer, guards)  → violations, each hard or soft
 *   repairAnswer(answer, ...)    → fixes what can be fixed in JS
 *
 * Guards are derived in JS rather than generated by the model: a 0.6B can't
 * emit reliable check specs, and asking it would cost an extra GPU burst per
 * question. The rules come from ASO-PLAYBOOK.md and from the shape of the
 * tracked data, both of which are knowable without inference.
 *
 * Anything repairable is fixed silently-but-disclosed (the panel shows what
 * changed). Only hard violations that JS cannot fix trigger one regeneration.
 */

import { INTENT } from "./assistant-core.js?v=9";

/** Words already in the App Store listing name — repeating them wastes chars. */
const TITLE_WORDS = ["snore", "timeline"];
const KEYWORD_FIELD_LIMIT = 100; // Apple's hard cap

/** Question asks for something to paste into the App Store keyword field. */
const KEYWORD_FIELD_RE =
  /\b(keyword field|keywords?|aso|listing|metadata)\b/i;
const DELIVERABLE_RE =
  /\b(give me|write|draft|generate|build|create|suggest|recommend|what should|which should|run in|use for|for (my|our|the) (app store )?(listing|keywords?|field))\b/i;

const words = (s) => String(s).toLowerCase().match(/[a-z0-9']+/g) ?? [];

/** Tokens that are worthless in a keyword field: pure numbers, years, stubs,
 *  and generic filler Apple already handles or that carries no search intent. */
const JUNK = new Set(["app", "apps", "the", "and", "for", "with", "your", "best", "top", "new", "pro", "ios", "iphone"]);
const isJunkToken = (w) => w.length < 3 || /^\d+$/.test(w) || JUNK.has(w);

/**
 * Words the user has told us to avoid, parsed from saved learnings.
 * Matches phrasings like "don't use lab", "never use X", "avoid X",
 * "exclude X" — so a chat instruction becomes an enforced rule rather than
 * a hint the model may or may not follow.
 */
export function blockedWords(memoryNotes = []) {
  const out = new Set();
  const re = /\b(?:don'?t use|do not use|never use|avoid|exclude|no)\s+(?:the\s+)?(?:keywords?\s+)?["']?([a-z0-9 ,'-]{2,60})["']?/gi;
  for (const n of memoryNotes) {
    const text = typeof n === "string" ? n : n?.text ?? "";
    for (const m of text.matchAll(re)) {
      for (const w of words(m[1])) {
        if (w.length >= 2 && !["the", "and", "for", "keyword", "keywords", "because", "with", "it", "will", "match"].includes(w)) out.add(w);
      }
    }
  }
  return out;
}

/** Internal prompt section headings — the model sometimes echoes these back. */
const LEAK_RE = /^\s*\**\s*(RETRIEVED FOR THIS QUESTION|KEYWORD TABLE|PLAYBOOK BUCKETS|COMPETITORS —|BIGGEST RANK MOVES|HIGH-DEMAND KEYWORDS|RATING HISTORY|KEYWORD DETAIL|SAVED LEARNINGS|KEYWORDS TRACKED|RATINGS \(|BASE DIGEST)/i;

// ---------------------------------------------------------------------------
// Plan
// ---------------------------------------------------------------------------

/**
 * Decide which guards apply. Returns [] for questions with nothing checkable,
 * so ordinary answers pay no cost at all.
 */
export function planGuards(question, data, cc, memoryNotes = []) {
  const q = String(question ?? "");
  const guards = [];
  const blocked = blockedWords(memoryNotes);

  // A keyword-field deliverable: the playbook's mechanical rules all apply.
  if (KEYWORD_FIELD_RE.test(q) && DELIVERABLE_RE.test(q)) {
    guards.push({ type: "keyword-field", cc: cc ?? "us", limit: KEYWORD_FIELD_LIMIT, blocked });
  }

  // Cheap and always worth running: the model must never quote our own
  // prompt scaffolding back at the user.
  guards.push({ type: "no-prompt-leak" });

  // Any data question: figures cited should exist in what we handed the model.
  if (INTENT?.strategy?.test?.(q) || /\b(rank|pop|rating|ratings|average|avg)\b/i.test(q)) {
    guards.push({ type: "grounded-keywords", cc: cc ?? "us" });
  }

  return guards;
}

// ---------------------------------------------------------------------------
// Check
// ---------------------------------------------------------------------------

/** First line only — that's where the prompt puts pasteable deliverables. */
const firstLine = (answer) => String(answer).split("\n")[0].trim();

/** Does the first line actually look like a keyword list? Prevents a
 *  mis-planned guard from mangling ordinary prose. */
function looksLikeKeywordList(line) {
  return line.length > 0 && line.length <= 220 && (line.match(/,/g) ?? []).length >= 2 && !/[.?!]$/.test(line);
}

export function checkAnswer(answer, guards, data) {
  const violations = [];
  const line = firstLine(answer);

  for (const g of guards) {
    if (g.type === "keyword-field") {
      if (!looksLikeKeywordList(line)) continue; // model answered in prose; nothing to validate
      const items = line.split(",").map((s) => s.trim()).filter(Boolean);
      const allWords = items.flatMap(words);

      if (line.length > g.limit) {
        violations.push({
          type: "keyword-field-length", severity: "hard", repairable: true, cc: g.cc,
          detail: `keyword field is ${line.length} chars, Apple's limit is ${g.limit}`,
        });
      }
      if (/,\s/.test(line)) {
        violations.push({
          type: "keyword-field-spaces", severity: "hard", repairable: true, cc: g.cc,
          detail: "spaces after commas waste characters",
        });
      }
      const repeatedTitle = [...new Set(allWords.filter((w) => TITLE_WORDS.includes(w)))];
      if (repeatedTitle.length) {
        violations.push({
          type: "keyword-field-title-words", severity: "hard", repairable: true, cc: g.cc,
          detail: `repeats words already in the app name (${repeatedTitle.join(", ")}); Apple combines fields automatically`,
        });
      }
      if (line.length < g.limit - 8) {
        violations.push({
          type: "keyword-field-underfilled", severity: "hard", repairable: true, cc: g.cc,
          detail: `only ${line.length} of ${g.limit} characters used; unused characters are wasted ranking surface`,
        });
      }
      const blocked = g.blocked ?? new Set();
      const usedBlocked = [...new Set(allWords.filter((w) => blocked.has(w)))];
      if (usedBlocked.length) {
        violations.push({
          type: "keyword-field-blocked", severity: "hard", repairable: true, cc: g.cc,
          detail: `uses words you asked to avoid (${usedBlocked.join(", ")})`,
        });
      }
      const dupes = [...new Set(allWords.filter((w, i) => allWords.indexOf(w) !== i))];
      if (dupes.length) {
        violations.push({
          type: "keyword-field-duplicates", severity: "hard", repairable: true, cc: g.cc,
          detail: `duplicate words (${dupes.join(", ")})`,
        });
      }

      // Words that appear in no tracked keyword for this market: possible invention.
      const tracked = new Set(Object.keys(data?.keywords?.latest?.[g.cc] ?? {}).flatMap(words));
      if (tracked.size) {
        const unknown = [...new Set(allWords)].filter((w) => w.length > 2 && !tracked.has(w));
        if (unknown.length) {
          violations.push({
            type: "keyword-field-untracked", severity: "soft", repairable: false,
            detail: `not present in any tracked ${g.cc.toUpperCase()} keyword: ${unknown.join(", ")}`,
          });
        }
      }
    }

    if (g.type === "no-prompt-leak") {
      const leaked = String(answer).split("\n").filter((l) => LEAK_RE.test(l));
      if (leaked.length) {
        violations.push({
          type: "prompt-leak", severity: "hard", repairable: true,
          detail: `echoed ${leaked.length} internal prompt heading(s) back into the answer`,
        });
      }
    }

    if (g.type === "grounded-keywords") {
      // Quoted phrases that look like keywords should be real tracked keywords.
      const quoted = [...String(answer).matchAll(/"([a-z][a-z0-9 '-]{4,40})"/gi)].map((m) => m[1].toLowerCase().trim());
      if (quoted.length) {
        const tracked = new Set(Object.keys(data?.keywords?.latest?.[g.cc] ?? {}).map((k) => k.toLowerCase()));
        const invented = quoted.filter((p) => !tracked.has(p));
        if (invented.length && tracked.size) {
          violations.push({
            type: "invented-keyword", severity: "soft", repairable: false,
            detail: `quoted as tracked keywords but not in the ${g.cc.toUpperCase()} data: ${invented.map((p) => `"${p}"`).join(", ")}`,
          });
        }
      }
    }
  }

  return violations;
}

// ---------------------------------------------------------------------------
// Repair
// ---------------------------------------------------------------------------

/**
 * Fix what JS can fix exactly. Returns the corrected answer plus a plain
 * description of every change, so the panel can disclose it.
 */
export function repairAnswer(answer, violations, data, cc = null, blocked = new Set()) {
  const applied = [];
  let out = String(answer);

  // Remove echoed prompt headings and the blank runs they leave behind.
  if (violations.some((v) => v.type === "prompt-leak")) {
    const kept = out.split("\n").filter((l) => !LEAK_RE.test(l));
    out = kept.join("\n").replace(/\n{3,}/g, "\n\n").trim();
    applied.push("removed internal prompt headings the model echoed back");
  }

  // We render as plain text, so leftover markdown emphasis is just noise.
  if (/\*\*|__/.test(out)) {
    out = out.replace(/\*\*(.+?)\*\*/g, "$1").replace(/__(.+?)__/g, "$1");
    applied.push("stripped markdown emphasis markers");
  }

  const kwFixes = violations.filter((v) => v.repairable && v.type.startsWith("keyword-field"));
  if (kwFixes.length) {
    const line = firstLine(out);
    if (looksLikeKeywordList(line)) {
      const before = line.length;
      // Rebuild per the playbook: single words, no title repeats, no dupes,
      // no spaces after commas, trimmed to the limit from the tail.
      const seen = new Set();
      const kept = [];
      for (const w of line.split(",").flatMap(words)) {
        if (TITLE_WORDS.includes(w) || seen.has(w) || isJunkToken(w) || blocked.has(w)) continue;
        seen.add(w);
        kept.push(w);
      }
      let rebuilt = kept.join(",");
      while (rebuilt.length > KEYWORD_FIELD_LIMIT && kept.length > 1) {
        kept.pop();
        rebuilt = kept.join(",");
      }

      // Fill the remaining budget. Every unused character is ranking surface
      // left on the table, so top up from the market's own tracked keywords,
      // highest playbook priority first.
      const market = cc ?? kwFixes.find((v) => v.cc)?.cc ?? "us";
      const pool = data?.keywords?.latest?.[market] ?? {};
      const ranked = Object.entries(pool)
        .map(([kw, v]) => ({ kw, pop: v.pop ?? 0, rank: v.rank ?? 999 }))
        // PUSH first (high popularity, winnable), then everything by popularity
        .sort((a, b) => {
          const pa = a.pop >= 50 && a.rank > 10 && a.rank <= 60 ? 1 : 0;
          const pb = b.pop >= 50 && b.rank > 10 && b.rank <= 60 ? 1 : 0;
          return pb - pa || b.pop - a.pop;
        });
      let added = 0;
      for (const r of ranked) {
        if (rebuilt.length >= KEYWORD_FIELD_LIMIT - 3) break;
        for (const w of words(r.kw)) {
          if (TITLE_WORDS.includes(w) || seen.has(w) || isJunkToken(w) || blocked.has(w)) continue;
          const next = rebuilt ? `${rebuilt},${w}` : w;
          if (next.length > KEYWORD_FIELD_LIMIT) continue;
          rebuilt = next;
          seen.add(w);
          added++;
        }
      }

      if (rebuilt && rebuilt !== line) {
        out = rebuilt + out.slice(firstLine(out).length);
        const bits = ["removed app-name words, duplicates, and spaces after commas"];
        if (added) bits.push(`filled the unused budget with ${added} high-popularity ${market.toUpperCase()} term(s)`);
        applied.push(`rewrote the keyword field (${before} → ${rebuilt.length}/${KEYWORD_FIELD_LIMIT} chars): ${bits.join("; ")}`);
      }
    }
  }

  const remaining = violations.filter((v) => !v.repairable && v.severity === "hard");
  const notes = violations.filter((v) => !v.repairable && v.severity === "soft");
  return { answer: out, applied, remaining, notes };
}

/** Corrective instruction for a single regeneration attempt. */
export function correctionPrompt(violations) {
  return (
    "Your previous answer had these problems:\n" +
    violations.map((v) => `- ${v.detail}`).join("\n") +
    "\nAnswer again, fixing them. Keep the same format rules."
  );
}
